func (u *Updater) prepare(path, version string) (string, string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", "", fmt.Errorf("read %s: %w", path, err)
	}
	if !versionPattern.Match(data) {
		return "", "", fmt.Errorf("version assignment not found in %s", path)
	}
	before := string(data)
	updated := versionPattern.ReplaceAllString(before, `${1}"`+version+`"${2}`)
	return before, updated, nil
}

func splitPaths(raw string) []string {
	parts := strings.FieldsFunc(raw, func(r rune) bool {
		return r == ',' || r == ';' || r == '\n'
	})
	paths := make([]string, 0, len(parts))
	for _, p := range parts {
		if trimmed := strings.TrimSpace(p); trimmed != "" {
			paths = append(paths, trimmed)
		}
	}
	if len(paths) == 0 {
		return []string{strings.TrimSpace(raw)}
	}
	return paths
}
